import numpy as np
from PIL import Image
a = np.array(Image.open('first_frame.png')).astype(int)
h,w,_ = a.shape
# coarse map: classify each 8x8 block
chars = np.full((18,32),' ')
for by in range(18):
    for bx in range(32):
        block = a[by*8:(by+1)*8, bx*8:(bx+1)*8]
        r,g,b = block[...,0].mean(), block[...,1].mean(), block[...,2].mean()
        if r>120 and r-g>50 and r-b>50:
            c='R'  # red liquid
        elif max(r,g,b)-min(r,g,b) < 25 and (r+g+b)/3 > 200:
            c='.'  # white/bright
        elif max(r,g,b)-min(r,g,b) < 25 and (r+g+b)/3 < 70:
            c='#'  # dark
        elif max(r,g,b)-min(r,g,b) < 25:
            c='-'  # gray
        elif g>r and g>b:
            c='g'
        elif b>r and b>g:
            c='b'
        elif r>g and r>b:
            c='o'
        else:
            c='?'
        chars[by,bx]=c
for row in chars:
    print(''.join(row))
EOF"

